pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: c.owner() should always return the contract's stored owner (the account that was set during initialization),
    // i.e., it must be independent of the caller. The mutant returns msg.sender, so when a different caller queries owner()
    // the returned value will differ. We fuzz the caller address to let the fuzzer find a caller different from the owner.
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address for clearer semantics
        vm.assume(caller != address(0));

        // initialize contract so owner is set to the deploying test contract (setUp deployed c from this address)
        // The initializer must be invoked from the test (the deployer), which is this contract; call initialize()
        c.initialize();

        // confirm stored owner as seen when called from the deployer (this contract)
        address ownerWhenCalledByDeployer = c.owner();

        // Now query owner() as the fuzzed caller. Use vm.prank to simulate external EOA caller.
        vm.prank(caller);
        address ownerWhenCalledByCaller = c.owner();

        // The universal property: the reference implementation returns the same owner address for ANY caller.
        // The mutant that returns msg.sender will differ when caller != stored owner. We assert they are equal,
        // which holds for the reference for all inputs and will fail for the mutant for some input (any caller != owner).
        assertTrue(ownerWhenCalledByDeployer == ownerWhenCalledByCaller);
    }
}

