        vm.prank(owner);
        c.initialize();
    }

    // fuzz the candidate newOwner; the property: for any newOwner != address(0), transferOwnership by current owner should succeed and owner() equals newOwner
    function testFuzz_property(address newOwner) public {
        // keep wide: only forbid the zero address if we want to check the normal behavior; but we need to allow zero for mutant to fail.
        // We'll test the general rule for ALL inputs: when caller is owner and newOwner != address(0), transferOwnership succeeds and owner()==newOwner.
