contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (who attempts the transfer) and newOwner (the address to transfer to).
    // Rule: only the current owner can successfully call transferOwnership; after call, owner()==newOwner iff the caller was the owner.
    // This holds for the correct contract for all inputs; the mutant (inverted onlyOwner) lets non-owners succeed, so the post-state differs for some inputs.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid the zero address for newOwner because transferOwnership reverts in P on zero address.
        // We allow caller==address(0) to be fuzzed (prank will treat zero address as EOA), but newOwner must not be zero.
        vm.assume(newOwner != address(0));

        // Setup: initialize c so it has an owner (the deployer in setUp is address(this)).
        c.initialize();
        address initialOwner = c.owner();
        // Ensure initial owner is this test contract (setUp deployer) — sanity
        // (No assert here; we rely on initialize having run)

        // Simulate caller invoking transferOwnership(newOwner).
        bool ok;
        // vm.prank with caller; if caller == address(0) this will set msg.sender to zero — acceptable for fuzz.
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: For the correct contract, only the current owner may succeed in transferring ownership.
        // That means: (ok == true) implies (caller == initialOwner) and owner() == newOwner;
        // and (caller != initialOwner) implies (ok == false) and owner() == initialOwner.
        // We condense this to a single boolean property that must hold for all inputs on the reference implementation.
        // The property expressed as a single assertTrue reads public state owner() and the observed ok result.

        // Build property boolean:
        bool prop;
        if (caller == initialOwner) {
            // when caller is owner, transferOwnership should succeed and owner() should be newOwner
            prop = ok && (c.owner() == newOwner);
        } else {
            // when caller is not owner, transferOwnership should fail and owner() should remain initialOwner
            prop = (!ok) && (c.owner() == initialOwner);
        }

        assertTrue(prop);
    }
}

