        // Only current owner (this test contract) can call transferOwnership
        c.transferOwnership(ownerAddr);

        // Now simulate ownerAddr calling updateAlloSettings with newAllo
        vm.prank(ownerAddr);
        bool ok;
        // call and record if it reverts or not
        try c.updateAlloSettings(newAllo) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, in the correct contract, if ownerAddr is the owner and call was made by that owner,
        // the updateAlloSettings should have set alloSettings to newAllo (and not reverted). Therefore the property:
        //   when the caller is the owner, updateAlloSettings succeeds and c.alloSettings() == newAllo
        // must hold for the reference implementation for all inputs. The mutant changes onlyOwner to compare owner()==address(0)
        // which will cause the function to revert (or fail to set) for the genuine owner in many cases. We assert the
        // universal property as a single assertion: that if call returned ok then the stored value equals newAllo.

        // The contract under test (reference C) will make ok == true and c.alloSettings() == newAllo for all ownerAddr != 0.
        // The mutant will often set ok == false or leave a different value, producing a failing assertion for some fuzz inputs.
        assertTrue(!(ok) == false || c.alloSettings() == newAllo);
        // Explanation of the single assertion above (kept as a single boolean):
        // If ok is true (call did not revert) then require c.alloSettings() == newAllo. If ok is false, the OR short-circuits
        // to true (since !(ok) == false is true), so the assertion still passes; only when ok==true but the stored value is
        // not newAllo will it fail. On the correct contract that never happens; on the mutant it can.
    }
}
